// Scaffold: builds tree from level-order array
struct Node* new_node(int d) {
    struct Node *n = malloc(sizeof(struct Node));
    n->data = d; n->left = n->right = NULL;
    return n;
}
struct Node* build_tree(int *arr, int n) {
    if (!n || arr[0] == -1) return NULL;
    struct Node **q = malloc(n * sizeof(struct Node*));
    int front = 0, back = 0;
    struct Node *root = new_node(arr[0]);
    q[back++] = root;
    int i = 1;
    while (front < back && i < n) {
        struct Node *cur = q[front++];
        if (i < n && arr[i] != -1) { cur->left = new_node(arr[i]); q[back++] = cur->left; } i++;
        if (i < n && arr[i] != -1) { cur->right = new_node(arr[i]); q[back++] = cur->right; } i++;
    }
    free(q);
    return root;
}
int main() {
    int n; scanf("%d", &n);
    int *arr = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    printf("%d\n", height(build_tree(arr, n)));
    free(arr);
    return 0;
}

